INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-death-registration-bdris-guide', 'মৃত্যুর ৪৫ দিনের মধ্যে আবেদন সরকারি ফি', 0, 1, 'বিনামূল্যে', 'সম্পূর্ণ বিনামূল্যে (০ টাকা)');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-death-registration-bdris-guide', 'মৃত্যুর ৪৬ দিন থেকে ৫ বছরের মধ্যে সরকারি ফি', 25, 1, 'অনলাইন / রসিদ', 'সরকারি নির্ধারিত ফি ২৫ টাকা');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-death-registration-bdris-guide', 'মৃত্যুর ৫ বছর পর যেকোনো সময় সরকারি ফি', 50, 1, 'অনলাইন / রসিদ', 'সরকারি নির্ধারিত ফি ৫০ টাকা');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-death-registration-bdris-guide', 'মৃত্যু সনদের ইংরেজি কপি ফি', 50, 1, 'অনলাইন / রসিদ', 'ইংরেজি ভার্সন সনদ ফি ৫০ টাকা');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-death-registration-bdris-guide', 'রেজিস্টার্ড চিকিৎসক/হাসপাতালের মৃত্যু সনদ বা কবরস্থান/শ্মশান রসিদ', 1, 0, 'মূল কপি ও স্ক্যান কপি', 'মৃত্যু হওয়া হাসপাতাল বা কবরস্থান পরিচালনা কমিটি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-death-registration-bdris-guide', 'মৃত ব্যক্তির জাতীয় পরিচয়পত্র (NID) বা অনলাইন জন্ম নিবন্ধন সনদ', 1, 0, 'স্ক্যান কপি', 'মৃত ব্যক্তির সংরক্ষিত নথিপত্র');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-death-registration-bdris-guide', 'আবেদনকারী ওয়ারিশের জাতীয় পরিচয়পত্র (NID)', 1, 0, 'ফটোকপি ও স্ক্যান কপি', 'আবেদনকারীর নিজস্ব এনআইডি');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-death-registration-bdris-guide', 1, 'bdris.gov.bd পোর্টালে অনলাইন ফরম পূরণ', 'bdris.gov.bd ওয়েবসাইটে গিয়ে মৃত্যু নিবন্ধন আবেদন সিলেক্ট করে ইউনিয়ন পরিষদ বা পৌরসভা বেছে নিন।', 'https://bdris.gov.bd', 'মৃত ব্যক্তির মৃত্যুর সঠিক তারিখ ও কারণ উল্লেখ করুন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-death-registration-bdris-guide', 2, 'প্রমাণপত্র আপলোড ও সাবমিট', 'চিকিৎসকের প্রত্যয়ন ও এনআইডি কপি আপলোড করে আবেদন সাবমিট করুন এবং আবেদন ফর্মের প্রিন্ট কপি ডাউনলোড করুন।', NULL, 'অ্যাপ্লিকেশন আইডি সংরক্ষণ করুন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-death-registration-bdris-guide', 3, 'কাগজপত্র জমা ও ডিজিটাল সনদ গ্রহণ', 'প্রিন্ট কপিসহ ইউনিয়ন পরিষদ বা ওয়ার্ড কাউন্সিলর অফিসে গিয়ে রসিদ কেটে কিউআর কোডযুক্ত আসল ডিজিটাল সনদপত্র গ্রহণ করুন।', NULL, 'সনদের কিউআর কোড স্ক্যান করে অনলাইন ডাটাবেজে সঠিকতা যাচাই করে নিন।');
INSERT INTO services (service_id, title_bn, title_en, category, sub_category, department_agency, summary, processing_time_sla, official_portal_url, application_url, citizen_charter_url, anti_broker_warning, grievance_remedy)
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-qazi-marriage-registration-fee-scale', 'দেনমোহরের প্রতি ১,০০০ টাকায় কাজি ফি (৪ লাখ টাকা পর্যন্ত)', 12.5, 1, 'কাজি অফিসে রসিদযুক্ত পেমেন্ট', '১.২৫% হার। যেমন: ১ লাখ টাকায় ১,২৫০ টাকা, ৪ লাখ টাকায় ৫,০০০ টাকা।');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-qazi-marriage-registration-fee-scale', '৪ লাখের অতিরিক্ত দেনমোহরে প্রতি লাখে ফি', 100, 1, 'কাজি অফিসে রসিদযুক্ত পেমেন্ট', '৪ লাখ টাকার অধিক যেকোনো পরিমাণের জন্য প্রতি লাখে মাত্র ১০০ টাকা।');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-qazi-marriage-registration-fee-scale', 'সর্বনিম্ন সরকারি বিবাহ নিবন্ধন ফি', 200, 1, 'নগদ রসিদ', 'দেনমোহর যত কমই হোক সর্বনিম্ন ফি ২০০ টাকা।');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-qazi-marriage-registration-fee-scale', 'কাজি বালাম বই তল্লাশি ফি (প্রতি বছর)', 50, 1, 'নগদ রসিদ', 'পুরাতন বিয়ের রেকর্ড খোঁজার সরকারি তলবানা ফি মাত্র ৫০ টাকা।');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-qazi-marriage-registration-fee-scale', 'বর ও কনের জাতীয় পরিচয়পত্র (NID) বা অনলাইন ডিজিটাল জন্ম সনদ', 1, 0, 'মূল কপি ও ফটোকপি', 'কনে ন্যূনতম ১৮ বছর ও বর ন্যূনতম ২১ বছর বয়স প্রমাণে আবশ্যক');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-qazi-marriage-registration-fee-scale', 'বর ও কনের পাসপোর্ট সাইজের স্পষ্ট ছবি (প্রত্যেকের ২ কপি)', 1, 0, 'রঙিন ছবি', 'স্টুডিও ল্যাব প্রিন্ট');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-qazi-marriage-registration-fee-scale', 'দুইজন প্রাপ্তবয়স্ক সুস্থমস্তিষ্ক পুরুষ সাক্ষী অথবা একজন পুরুষ ও দুইজন নারী সাক্ষীর এনআইডি', 1, 0, 'এনআইডি ফটোকপি', 'সাক্ষীদের নিজস্ব জাতীয় পরিচয়পত্র');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-qazi-marriage-registration-fee-scale', 'কনের অভিভাবক / উকিল বাবার জাতীয় পরিচয়পত্র', 1, 0, 'এনআইডি ফটোকপি', 'কনের পিতা বা আইনগত অভিভাবক');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-qazi-marriage-registration-fee-scale', 1, 'বর ও কনের বয়স ও পরিচয় যাচাই', 'কনের বয়স ন্যূনতম ১৮ এবং বরের বয়স ন্যূনতম ২১ বছর হতে হবে। কাজি সরকারি নিয়মে এনআইডি বা জন্ম সনদ অনলাইনে যাচাই করবেন।', NULL, 'বাল্যবিবাহ সম্পূর্ণ নিষিদ্ধ ও আইনত দণ্ডনীয় অপরাধ।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-qazi-marriage-registration-fee-scale', 2, 'দেনমোহর নির্ধারণ ও সরকারি স্কেল অনুযায়ী ফি হিসাব', 'দেনমোহর অনুযায়ী সরকারি স্কেল মেনে ফি হিসাব করুন এবং অতিরিক্ত কোনো টাকা ছাড়া রসিদ সংগ্রহ করুন।', NULL, 'কাজি যদি রসিদ ছাড়া ১০-২০ হাজার টাকা চায় তবে তাকে সরকারি গেজেট দেখান।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-qazi-marriage-registration-fee-scale', 3, 'বালাম বইয়ে স্বাক্ষর ও নিকাহনামা গ্রহণ', 'সরকারি বালাম বইয়ে বর, কনে, উকিল বাবা ও সাক্ষীদের স্বাক্ষর সম্পন্ন করে সার্টিফাইড নিকাহনামা সংগ্রহ করুন।', NULL, 'নিকাহনামার বালাম নম্বর, পৃষ্ঠা নম্বর ও ভলিউম নম্বর লিখে রাখুন।');
