INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-ec-new-voter-registration-form-2', 'নতুন ভোটার ও প্রথমবার এনআইডি আবেদন ফি', 0, 1, 'বিনামূল্যে', 'আইনত সম্পূর্ণ বিনামূল্যে (০ টাকা)');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-ec-new-voter-registration-form-2', '১৭ ডিজিটের অনলাইন জন্ম নিবন্ধন সনদ (বাংলা ও ইংরেজি)', 1, 0, 'অনলাইন স্ক্যান কপি', 'bdris.gov.bd পোর্টাল');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-ec-new-voter-registration-form-2', 'পিতা ও মাতার জাতীয় পরিচয়পত্র (NID) কপি', 1, 0, 'ফটোকপি', 'বাবা ও মায়ের এনআইডি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-ec-new-voter-registration-form-2', 'শিক্ষাগত যোগ্যতার সনদপত্র (এসএসসি/জেএসসি/৮ম শ্রেণি)', 0, 0, 'ফটোকপি', 'শিক্ষাপ্রতিষ্ঠান সনদ');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-ec-new-voter-registration-form-2', 'বর্তমান ঠিকানার বিদ্যুৎ/গ্যাস বিলের কপি বা হোল্ডিং ট্যাক্স রসিদ', 1, 0, 'ফটোকপি', 'বাসার ইউটিলিটি বিল');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-ec-new-voter-registration-form-2', 'চেয়ারম্যান বা ওয়ার্ড কাউন্সিলরের নাগরিকত্ব প্রত্যয়নপত্র', 1, 0, 'মূল কপি', 'স্থানীয় কাউন্সিলর বা ইউপি অফিস');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-ec-new-voter-registration-form-2', 1, 'services.nidw.gov.bd পোর্টালে অনলাইন ফরম-২ পূরণ', 'নির্বাচন কমিশন পোর্টালে গিয়ে ''নতুন ভোটার আবেদন'' সিলেক্ট করে ব্যক্তিগত তথ্য ও ঠিকানা পূরণ করে সাবমিট করুন।', 'https://services.nidw.gov.bd', 'নামের বানান যেন জন্ম সনদের সাথে হুবহু এক থাকে।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-ec-new-voter-registration-form-2', 2, 'উপজেলা নির্বাচন অফিসে বায়োমেট্রিক প্রদান', 'আবেদনের প্রিন্ট কপি নিয়ে উপজেলা নির্বাচন অফিসে গিয়ে ১০ আঙুলের ছাপ, আইরিশ ও ছবি দিন।', NULL, 'সাদা পোশাক পরিহার করে গাঢ় রঙের পোশাক পরে ছবি তুলতে যান।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-ec-new-voter-registration-form-2', 3, 'ডিজিটাল এনআইডি অনলাইন ডাউনলোড', 'মোবাইলে এসএমএস আসলে পোর্টাল থেকে বিনামূল্যে ডিজিটাল অনলাইন স্মার্ট এনআইডি ডাউনলোড করে ল্যামিনেট করে ব্যবহার করুন।', NULL, 'অনলাইন কপিটি মূল কার্ড আসার পূর্ব পর্যন্ত সকল কাজে শতভাগ বৈধ।');
