INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-national-savings-sanchayapatra-guide', 'মুনাফার ওপর উৎসে কর (টিআইএন ও রিটার্ন দাখিলের প্রমাণ থাকলে)', 0, 1, 'স্বয়ংক্রিয় কর্তন', 'মুনাফার ওপর মাত্র ৫% উৎসে কর কাটা হয়।');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-national-savings-sanchayapatra-guide', 'মুনাফার ওপর উৎসে কর (রিটার্ন দাখিলের প্রমাণ না থাকলে)', 0, 1, 'স্বয়ংক্রিয় কর্তন', 'মুনাফার ওপর ১০% উৎসে কর কাটা হয়।');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-national-savings-sanchayapatra-guide', 'বিনিয়োগকারীর জাতীয় পরিচয়পত্র (NID) ও ২ কপি পাসপোর্ট ছবি', 1, 0, 'মূল কপি ও ফটোকপি', 'বিনিয়োগকারীর সংরক্ষিত কপি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-national-savings-sanchayapatra-guide', 'নমিনির জাতীয় পরিচয়পত্র/জন্ম সনদ ও ১ কপি সত্যায়িত ছবি', 1, 1, 'সত্যায়িত কপি', 'নমিনির এনআইডি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-national-savings-sanchayapatra-guide', 'বিনিয়োগকারীর ই-টিআইএন ও রিটার্ন দাখিলের প্রমাণপত্র (PSR)', 1, 0, 'অনলাইন একনলেজমেন্ট স্লিপ', 'এনবিআর ইনকাম ট্যাক্স পোর্টাল');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-national-savings-sanchayapatra-guide', 'বিনিয়োগকারীর নিজস্ব এমআইসিআর (MICR) ব্যাংক চেকের পাতা', 1, 0, 'মূল চেক', 'বিনিয়োগকারীর ব্যাংক হিসাবের চেকবই');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-national-savings-sanchayapatra-guide', 1, 'ব্যাংক বা ডাকঘর থেকে ফরম সংগ্রহ ও পূরণ', 'সোনালী ব্যাংক, বাংলাদেশ ব্যাংক বা ডাকঘরের সঞ্চয়পত্র কাউন্টার থেকে ফরম পূরণ করুন।', NULL, 'পরিবার সঞ্চয়পত্র নারীদের জন্য এবং পেনশনার সঞ্চয়পত্র সরকারি/আধা-সরকারি অবসরপ্রাপ্তদের জন্য প্রযোজ্য।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-national-savings-sanchayapatra-guide', 2, 'চেক ও নথিপত্র জমাদান', 'এনআইডি, টিআইএন, রিটার্ন জমার কপি ও নিজের ব্যাংক অ্যাকাউন্টের চেক কাউন্টারে জমা দিন।', NULL, 'চেকটি ''Account Payee'' হিসেবে ইস্যু করুন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-national-savings-sanchayapatra-guide', 3, 'সঞ্চয়পত্র রসিদ ও ব্যাংকিং ইএফটি মুনাফা গ্রহণ', 'কাউন্টার থেকে সঞ্চয়পত্রের মূল রশিদ বুঝে নিন। নির্ধারিত প্রতি মাসে আপনার ব্যাংক অ্যাকাউন্টে মুনাফা জমা হবে।', NULL, 'মুনাফা তোলার জন্য ব্যাংকে যাওয়ার দরকার নেই, ডেবিট কার্ড দিয়ে যেকোনো এটিএম থেকে টাকা তোলা যায়।');
INSERT INTO services (service_id, title_bn, title_en, category, sub_category, department_agency, summary, processing_time_sla, official_portal_url, application_url, citizen_charter_url, anti_broker_warning, grievance_remedy)
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-suborno-nagorik-disability-smart-card', 'সুবর্ণ নাগরিক কার্ড সরকারি ফি', 0, 1, 'বিনামূল্যে', 'সম্পূর্ণ বিনামূল্যে (০ টাকা)');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-suborno-nagorik-disability-smart-card', 'আবেদনকারীর অনলাইন জন্ম সনদ বা জাতীয় পরিচয়পত্র (NID)', 1, 0, 'মূল কপি ও ফটোকপি', 'এনআইডি বা BDRIS পোর্টাল');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-suborno-nagorik-disability-smart-card', 'উপজেলা স্বাস্থ্য কমপ্লেক্সের মেডিকেল অফিসারের প্রত্যয়নপত্র', 1, 0, 'মূল কপি', 'উপজেলা স্বাস্থ্য কমপ্লেক্সের চিকিৎসক');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-suborno-nagorik-disability-smart-card', 'আবেদনকারীর পাসপোর্ট সাইজের রঙিন ছবি (৩ কপি)', 1, 0, 'ছবি', 'স্টুডিও ল্যাব প্রিন্ট');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-suborno-nagorik-disability-smart-card', 'পিতা/মাতা বা অভিভাবকের জাতীয় পরিচয়পত্রের কপি', 1, 0, 'ফটোকপি', 'অভিভাবকের এনআইডি');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-suborno-nagorik-disability-smart-card', 1, 'dis.gov.bd পোর্টালে অনলাইন নিবন্ধন', 'প্রতিবন্ধিতা শনাক্তকরণ জরিপ পোর্টালে প্রবেশ করে ব্যক্তিগত তথ্য ও প্রতিবন্ধিতার ধরন নির্বাচন করে আবেদন করুন।', 'http://dis.gov.bd', 'সচল মোবাইল নম্বর দিন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-suborno-nagorik-disability-smart-card', 2, 'উপজেলা সমাজসেবা মেডিকেল বোর্ডে মূল্যায়ন', 'উপজেলা সমাজসেবা অফিসে গিয়ে নির্ধারিত দিনে মেডিকেল অফিসারের সামনে উপস্থিত হয়ে প্রতিবন্ধিতার মাত্রা যাচাই সম্পন্ন করান।', NULL, 'পূর্বের কোনো চিকিৎসার প্রেসক্রিপশন বা রিপোর্ট থাকলে সাথে নিন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-suborno-nagorik-disability-smart-card', 3, 'ডিজিটাল সুবর্ণ নাগরিক স্মার্ট কার্ড গ্রহণ', 'অনুমোদন শেষে উপজেলা সমাজসেবা কার্যালয় থেকে কিউআর কোডযুক্ত ডিজিটাল স্মার্ট কার্ড সম্পূর্ণ বিনামূল্যে সংগ্রহ করুন।', NULL, 'কার্ড পাওয়ার পর সাথে সাথে ভাতার জন্য সমাজসেবা অফিসে আবেদন করুন।');
