INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-automated-echallan-govt-fee-payment', 'এ-চালান সিস্টেম সরকারি ফি', 0, 1, 'বিনামূল্যে', 'পদ্ধতিগত চার্জ সম্পূর্ণ ফ্রি (০ টাকা)');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-automated-echallan-govt-fee-payment', 'সেবা সংশ্লিষ্ট সরকারি নির্দিষ্ট ট্রেজারি কোড (যেমন: পুলিশ ক্লিয়ারেন্স ১-২২১১-০০০০-২০৪৩)', 1, 0, 'চালান কোড', 'সংশ্লিষ্ট সরকারি নির্দেশিকা');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-automated-echallan-govt-fee-payment', 'জমা প্রদানকারীর জাতীয় পরিচয়পত্র (NID) নম্বর ও সচল মোবাইল', 1, 0, 'নম্বর ইনপুট', 'নাগরিকের এনআইডি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-automated-echallan-govt-fee-payment', 'বিকাশ, নগদ, রকেট, ব্যাংক কার্ড বা ইন্টারনেট ব্যাংকিং', 1, 0, 'পেমেন্ট গেটওয়ে', 'অনলাইন অ্যাকাউন্ট');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-automated-echallan-govt-fee-payment', 1, 'echallan.gov.bd পোর্টালে কোড নির্বাচন', 'পোর্টালে গিয়ে সংশ্লিষ্ট মন্ত্রণালয় নির্বাচন করে সঠিক অর্থনৈতিক কোড ও জেলার নাম বেছে নিন।', 'https://echallan.gov.bd', 'চালান কোড যেন কোনো অবস্থাতেই ভুল না হয়।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-automated-echallan-govt-fee-payment', 2, 'ব্যক্তিগত তথ্য ও ফি এর পরিমাণ প্রদান', 'জমা প্রদানকারীর নাম, এনআইডি ও টাকার পরিমাণ লিখে পেমেন্ট অপশন নির্বাচন করুন।', NULL, 'টাকার পরিমাণ সরকারি ফির সাথে হুবহু মিলাতে হবে।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-automated-echallan-govt-fee-payment', 3, 'অনলাইন পেমেন্ট ও এ-চালান পিডিএফ ডাউনলোড', 'বিকাশ/কার্ডে পেমেন্ট সফল হওয়ার সাথে সাথে সরকারি বারকোডযুক্ত চালান প্রিন্ট করে সংশ্লিষ্ট অফিসে জমা দিন।', NULL, 'চালান কপি মোবাইলে ও ড্রাইভে সেভ করে রাখুন।');
INSERT INTO services (service_id, title_bn, title_en, category, sub_category, department_agency, summary, processing_time_sla, official_portal_url, application_url, citizen_charter_url, anti_broker_warning, grievance_remedy)
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-citizenship-character-certificate-up-citycorp', 'নাগরিকত্ব ও চারিত্রিক সনদপত্র সরকারি রসিদ ফি', 30, 1, 'কাউন্টার রসিদ', 'ইউনিয়ন পরিষদে ২০-৩০ টাকা, পৌরসভা বা সিটি কর্পোরেশনে সর্বোচ্চ ৫০ টাকা।');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-citizenship-character-certificate-up-citycorp', 'আবেদনকারীর জাতীয় পরিচয়পত্র (NID) বা অনলাইন জন্ম নিবন্ধন সনদ', 1, 0, 'মূল কপি ও ফটোকপি', 'নাগরিকের পরিচয়পত্র');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-citizenship-character-certificate-up-citycorp', 'পিতা ও মাতার জাতীয় পরিচয়পত্রের কপি', 1, 0, 'ফটোকপি', 'পিতা-মাতার এনআইডি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-citizenship-character-certificate-up-citycorp', 'বর্তমান বাসস্থানের হোল্ডিং ট্যাক্স রসিদ বা বিদ্যুৎ বিল', 1, 0, 'ফটোকপি', 'বাসার বিদ্যুৎ বিল');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-citizenship-character-certificate-up-citycorp', 'পাসপোর্ট সাইজের স্পষ্ট রঙিন ছবি (১ কপি)', 1, 0, 'ছবি', 'স্টুডিও ল্যাব প্রিন্ট');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-citizenship-character-certificate-up-citycorp', 1, 'কাউন্সিলর বা ইউপি কার্যালয়ে আবেদন', 'ওয়ার্ড কাউন্সিলর বা ইউনিয়ন পরিষদ কার্যালয়ে গিয়ে নির্ধারিত আবেদন ফর্মে তথ্য পূরণ করে নথিপত্র সংযুক্ত করুন।', NULL, 'পিতার নাম ও স্থায়ী ঠিকানা ভোটার কার্ডের সাথে মিলিয়ে লিখুন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-citizenship-character-certificate-up-citycorp', 2, 'স্থানীয় সদস্য বা কাউন্সিলর কর্তৃক শনাক্তকরণ', 'সংশ্লিষ্ট ইউপি সদস্য বা ওয়ার্ড কাউন্সিলর আবেদনকারীকে ওই এলাকার স্থায়ী বাসিন্দা হিসেবে প্রত্যয়ন করবেন।', NULL, 'সরাসরি উপস্থিত হওয়া সর্বোত্তম।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-citizenship-character-certificate-up-citycorp', 3, 'অফিসিয়াল সিলমোহর ও সনদপত্র গ্রহণ', 'কাউন্সিলর বা চেয়ারম্যানের স্বাক্ষর ও গোল সিলমোহরযুক্ত নাগরিকত্ব ও চারিত্রিক সনদ রসিদসহ সংগ্রহ করুন।', NULL, 'সনদে স্মারক নম্বর ও তারিখ নিশ্চিত করুন।');
INSERT INTO services (service_id, title_bn, title_en, category, sub_category, department_agency, summary, processing_time_sla, official_portal_url, application_url, citizen_charter_url, anti_broker_warning, grievance_remedy)
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'মোটরকার (১৫০০ সিসি পর্যন্ত) ফিটনেস ফি ও ১৫% ভ্যাট', 1179, 1, 'অনলাইন গেটওয়ে বা অনুমোদিত ব্যাংক', 'মূল ফি ১,০২৫ টাকা + ১৫% ভ্যাট ১৫৪ টাকা = ১,১৭৯ টাকা।');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'মাইক্রোবাস ও জিপ ফিটনেস ফি ও ১৫% ভ্যাট', 1725, 1, 'অনলাইন গেটওয়ে বা অনুমোদিত ব্যাংক', 'মূল ফি ১,৫০০ টাকা + ১৫% ভ্যাট ২২৫ টাকা = ১,৭২৫ টাকা।');
INSERT INTO service_fees (service_id, category_name, amount_bdt, vat_included, payment_method, remarks) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'বাস ও ভারী বাণিজ্যিক যান ফিটনেস ফি ও ভ্যাট', 2472, 1, 'অনলাইন গেটওয়ে বা ব্যাংক', 'মূল ফি ২,১৫০ টাকা + ১৫% ভ্যাট অন্তর্ভুক্ত।');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'পূর্ববর্তী মূল ফিটনেস সনদের কপি', 1, 0, 'মূল কপি', 'গাড়ির পূর্বের ফিটনেস পেপার');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'হালনাগাদ ট্যাক্স টোকেনের মূল কপি ও ফটোকপি', 1, 0, 'মূল কপি ও ফটোকপি', 'ব্যাংক থেকে নবায়িত ট্যাক্স টোকেন');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'মোটরযানের ডিজিটাল রেজিস্ট্রেশন স্মার্ট কার্ড / ব্লু-বুক', 1, 0, 'মূল কপি', 'বিআরটিএ মূল কার্ড');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 'ফিটনেস ফি পরিশোধের অনলাইন ব্যাংক রসিদ বা এ-চালান', 1, 0, 'প্রিন্ট কপি', 'BSP অনলাইন গেটওয়ে বা ব্যাংক');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 1, 'bsp.brta.gov.bd পোর্টালে ফি পরিশোধ ও সময় বুকিং', 'বিআরটিএ সার্ভিস পোর্টালে গাড়ি রেজিস্ট্রেশন নম্বর দিন। নির্ধারিত ফি অনলাইনে পরিশোধ করে গাড়ি পরিদর্শনের (VIC) তারিখ নির্বাচন করুন।', 'https://bsp.brta.gov.bd', 'মিরপুর বা ইকুরিয়া ভিআইসি সেন্টার বেছে নিন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 2, 'বিআরটিএ সার্কেলে গাড়ি নিয়ে পরিদর্শন সম্পন্ন করা', 'নির্ধারিত দিনে গাড়ি নিয়ে বিআরটিএ টেস্টিং গ্রাউন্ডে যান। মোটরযান পরিদর্শক ব্রেক, লাইট, টায়ার, এমিশন ও ইঞ্জিন চেসিস নম্বর যাচাই করবেন।', NULL, 'গাড়ির সব লাইট ও ইন্ডিকেটর সচল থাকা নিশ্চিত করুন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-brta-vehicle-fitness-certificate-renewal', 3, 'ডিজিটাল ফিটনেস সনদপত্র গ্রহণ', 'টেস্টে পাস করার সাথে সাথে পরিদর্শক সিস্টেমের মাধ্যমে অনুমোদন দেবেন এবং নতুন ১ বছর মেয়াদি ডিজিটাল ফিটনেস সার্টিফিকেট সাথে সাথে প্রদান করা হবে।', NULL, 'নতুন কিউআর কোডযুক্ত সার্টিফিকেট সাথে সাথে গাড়িতে সংরক্ষণ করুন।');